export default function SectionBackdrop({
    className,
    showGrid = true,
    showGlows = true,
    reticules = 'both',
    graphic = 'reticule',
    variant,
    ...props
}: SectionBackdropProps) {
    const selectedGraphic = variant ?? graphic;
    const isWheel = selectedGraphic === 'wheel' || selectedGraphic === 2 || selectedGraphic === '2';
    const showLeftGraphic = reticules === 'both' || reticules === 'left';
    const showRightGraphic = reticules === 'both' || reticules === 'right';

    const GraphicComponent = isWheel ? WheelGraphic : TelemetryReticule;

    return (
        <div
            aria-hidden={true}
            className={cn("pointer-events-none -z-10 absolute inset-0 overflow-hidden opacity-100", className)}
            {...props}
        >
            {/* Ambient Corner Lights */}
            {showGlows && (
                <>
                    <div className="absolute top-0 left-0 w-125 h-125 bg-primary/15 blur-[120px] rounded-full pointer-events-none -translate-x-1/2 -translate-y-1/2" />
                    <div className="absolute bottom-0 right-0 w-150 h-150 bg-primary/15 blur-[130px] rounded-full pointer-events-none translate-x-1/3 translate-y-1/3" />
                    <div className="absolute top-0 left-0 w-125 h-125 bg-primary/20 blur-[130px] rounded-full pointer-events-none -translate-x-1/2 -translate-y-1/2" />
                    <div className="absolute bottom-0 right-0 w-150 h-150 bg-sky-500/15 blur-[140px] rounded-full pointer-events-none translate-x-1/3 translate-y-1/3" />
                </>
            )}

            {/* CAD Drafting Grid Texture Overlay */}
            {showGrid && (
                <div
                    aria-hidden="true"
                    className="absolute inset-0 pointer-events-none opacity-25 bg-[linear-gradient(to_right,var(--background)_1px,transparent_1px),linear-gradient(to_bottom,var(--background)_1px,transparent_1px)] bg-[size:40px_40px]"
                />
            )}

            {/* Kinetic Graphic Watermarks */}
            {showRightGraphic && (
                <GraphicComponent className="absolute right-0 top-1/2 translate-x-1/2 -translate-y-1/2" />
            )}
            {showLeftGraphic && (
                <GraphicComponent className="absolute left-0 top-1/2 -translate-x-1/2 -translate-y-1/2" />
            )}
        </div>
    );
}

export { SectionBackdrop, TelemetryReticule, WheelGraphic };
